<?php $editing=(bool)$service;?>
<div class="section-heading"><div><div class="eyebrow">Catálogo</div><h1><?=$editing?'Editar serviço':'Novo serviço'?></h1></div><a class="btn btn-light" href="/services">Voltar</a></div><div class="card"><div class="card-body"><form method="post" action="<?=$editing?'/services/'.(int)$service['id'].'/update':'/services/store'?>"><?php echo \App\Core\CSRF::field();?><div class="row g-3"><div class="col-md-6"><label class="form-label">Nome</label><input name="name" class="form-control" required maxlength="150" value="<?=htmlspecialchars($service['name']??'',ENT_QUOTES,'UTF-8')?>"></div><div class="col-md-3"><label class="form-label">Duração</label><div class="input-group"><input name="duration_minutes" type="number" min="5" max="1440" value="<?=htmlspecialchars((string)($service['duration_minutes']??30))?>" class="form-control" required><span class="input-group-text">min</span></div></div><div class="col-md-3"><label class="form-label">Preço</label><input name="price" type="number" step="0.01" min="0" class="form-control" value="<?=htmlspecialchars((string)($service['price']??''))?>" required></div><div class="col-12"><label class="form-label">Descrição</label><textarea class="form-control" name="description" rows="3"><?=htmlspecialchars($service['description']??'',ENT_QUOTES,'UTF-8')?></textarea></div><?php if($editing):?><div class="col-12"><label class="form-check"><input class="form-check-input" type="checkbox" name="active" value="1" <?=$service['active']?'checked':''?>> Serviço ativo e disponível para agendamento</label></div><?php endif;?></div><button class="btn btn-primary mt-4">Salvar serviço</button></form></div></div><?php if($editing):?><form class="mt-3" method="post" action="/services/<?=(int)$service['id']?>/deactivate" onsubmit="return confirm('Inativar este serviço? O histórico será preservado.')"><?php echo \App\Core\CSRF::field();?><button class="btn btn-outline-danger">Inativar serviço</button></form><?php endif;?>
